// Worker entry for the Cloudflare copy: the OpenNext handler for every request, plus the daily Cron Trigger.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

import { isPrivateContent, notFound } from "./lib/private-content";

type Env = { CRON_SECRET?: string };

export default {
  // Lesson files are read by the server through ASSETS only: a request from outside gets 404.
  fetch(req: Request, env: unknown, ctx: unknown) {
    if (isPrivateContent(new URL(req.url).pathname)) return notFound();
    return handler.fetch(req, env, ctx);
  },
  async scheduled(event: { cron?: string }, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    // Every 15 minutes: reminders in each learner's own quarter hour and removal of deleted accounts (slice 4). Up to 4 calls of 25.
    if (event?.cron === "*/15 * * * *") {
      ctx.waitUntil((async () => {
        for (let i = 0; i < 4; i++) {
          const res: Response = await handler.fetch(new Request("https://internal/api/cron/reminders", { headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` } }), env, ctx);
          const text = await res.text();
          console.log(`cron reminders ${i + 1}: ${res.status} ${text}`);
          if (!res.ok || !text.includes('"more":true')) break;
        }
      })());
      return;
    }
    // Calls the daily routes directly; the secret keeps them closed to the public.
    // daily: streaks and reminders. billing: renewals, grace period, retries and billing reminders (slice 5).
    for (const job of ["daily", "billing"]) {
      const req = new Request(`https://internal/api/cron/${job}`, {
        headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
      });
      ctx.waitUntil(
        handler.fetch(req, env, ctx).then(async (res: Response) => {
          console.log(`cron ${job}: ${res.status} ${await res.text()}`);
        }),
      );
    }
  },
};

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
